#!/bin/sh
# Assembles the derived dbaas-crd chart from the operator chart's CRD templates.
#
# CRD definitions are canonical in the operator chart
# (dbaas-operator/helm-templates/dbaas-operator/templates/crd-*.yaml,
# regenerated by `make sync-helm-crds`). This script only copies them into a
# standalone chart; it never modifies CRD content. The wrapper metadata
# (Chart.yaml, values.yaml) is regenerated here; deployments may override it
# with their own wrapper.
#
# Usage:
#   sh build-crd-chart.sh <operator-chart-dir> <output-dir>

set -eu

OPERATOR_CHART_DIR="${1:?usage: build-crd-chart.sh <operator-chart-dir> <output-dir>}"
OUT_DIR="${2:?usage: build-crd-chart.sh <operator-chart-dir> <output-dir>}"

OPERATOR_CHART_DIR=$(cd "$OPERATOR_CHART_DIR" && pwd)

OPERATOR_VERSION=$(sed -n 's/^version:[[:space:]]*//p' "$OPERATOR_CHART_DIR/Chart.yaml" | tr -d "\"'")
if [ -z "$OPERATOR_VERSION" ]; then
  echo "ERROR: cannot read version from $OPERATOR_CHART_DIR/Chart.yaml" >&2
  exit 1
fi

mkdir -p "$OUT_DIR/templates"

CRD_COUNT=0
for crd in "$OPERATOR_CHART_DIR"/templates/crd-*.yaml; do
  [ -e "$crd" ] || continue
  cp "$crd" "$OUT_DIR/templates/"
  CRD_COUNT=$((CRD_COUNT + 1))
done
if [ "$CRD_COUNT" -eq 0 ]; then
  echo "ERROR: no crd-*.yaml templates found in $OPERATOR_CHART_DIR/templates" >&2
  exit 1
fi

cat > "$OUT_DIR/Chart.yaml" <<EOF
apiVersion: v2
name: dbaas-crd
description: DBaaS custom resource definitions (derived from the dbaas-operator chart)
type: application
version: ${OPERATOR_VERSION}
appVersion: "1.0"
EOF

cat > "$OUT_DIR/values.yaml" <<EOF
# The dbaas-crd chart ships the operator chart's CRD templates, which are gated
# on DBAAS_OPERATOR_ENABLED. It must stay true so the CRDs render.
DBAAS_OPERATOR_ENABLED: true
EOF

echo "Assembled dbaas-crd chart in $OUT_DIR: $CRD_COUNT CRDs, version ${OPERATOR_VERSION}"
